CREATE TABLE rule_survival_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),skill_rule_id bigint NOT NULL UNIQUE REFERENCES rule_skill(rule_id));
CREATE TABLE rule_survival_operation(rule_id bigint NOT NULL REFERENCES rule_survival_mechanic(rule_id),operation_code text NOT NULL CHECK(operation_code IN('hunt-animals','trap-animals','avoid-exposure','locate-food','locate-fresh-water','produce-fire','find-shelter','avoid-dangerous-flora-fauna','avoid-getting-lost','handle-hazardous-climate')),availability_required boolean NOT NULL,display_order smallint NOT NULL CHECK(display_order>0),PRIMARY KEY(rule_id,operation_code),UNIQUE(rule_id,display_order),CHECK(availability_required=(operation_code IN('locate-food','locate-fresh-water','produce-fire'))));
COMMENT ON TABLE rule_survival_operation IS 'CE-SKILL-016 paired-source wilderness Survival capabilities, including explicit availability gates.';
